def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    total_opp_c = 0
    total_my_d = 0
    for a, b in history:
        if b == 'C':
            total_opp_c += 1
        if a == 'D':
            total_my_d += 1
    total_opp_d = n - total_opp_c

    if total_opp_c == 0:
        return 'D'

    punished = 0
    tolerated = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'D':
                punished += 1
            else:
                tolerated += 1

    recent = history[-10:]
    rn = len(recent)
    opp_c_recent = 0
    opp_d_recent = 0
    my_c_recent = 0
    for a, b in recent:
        if b == 'C':
            opp_c_recent += 1
        else:
            opp_d_recent += 1
        if a == 'C':
            my_c_recent += 1

    high_coop = total_opp_c * 4 >= n * 3
    very_coop = total_opp_c * 20 >= n * 19
    recent_high_coop = opp_c_recent * 10 >= rn * 8

    pushover = False
    if punished == 0 and tolerated >= 1 and total_opp_c == n:
        pushover = True
    elif punished == 0 and tolerated >= 3 and high_coop:
        pushover = True
    elif punished <= 1 and tolerated >= 4 and high_coop and recent_high_coop:
        pushover = True
    elif total_opp_d <= 2 and tolerated >= 2 and punished == 0 and n > 12:
        pushover = True

    # If this opponent has just punished our isolated test, repair cooperation.
    if n >= 3 and history[-2][0] == 'D' and history[-2][1] == 'C':
        if my_last == 'C' and opp_last == 'D':
            if high_coop or recent_high_coop or opp_c_recent >= rn - 2 or total_opp_d <= 3:
                return 'C'

    if opp_last == 'D':
        if my_last == 'D':
            if pushover or recent_high_coop or (opp_c_recent >= 6 and total_opp_c * 2 >= n):
                return 'C'
            return 'D'

        if pushover and opp_d_recent <= 2:
            return 'C'

        if high_coop and opp_d_recent <= 2:
            if rng.random() < 0.70:
                return 'D'
            return 'C'

        if total_opp_c * 2 >= n and opp_d_recent <= 4:
            if rng.random() < 0.18:
                return 'C'
            return 'D'

        return 'D'

    if opp_last == 'C':
        if my_last == 'D':
            if pushover:
                return 'D'
            if total_opp_c * 2 <= n:
                return 'D'
            return 'C'

        if pushover:
            return 'D'

        if n == 98:
            if total_opp_d * 2 >= n or opp_d_recent >= 4:
                return 'D'
            return 'C'

        if n > 20 and (high_coop or recent_high_coop):
            if very_coop:
                p = 0.15
            elif high_coop:
                p = 0.09
            else:
                p = 0.03

            if n >= 85:
                p *= 0.55

            if punished > 0 and tolerated < 3:
                p *= 0.25 if punished < 4 else 0.10
            elif punished * 2 <= tolerated and tolerated >= 3:
                p *= 1.35

            if rng.random() < p:
                return 'D'

        return 'C'

    return 'C'
